script:
(function () {
  'use strict';

  var video = document.getElementById('cameraVideo');
  var previewWrap = document.getElementById('cameraPreviewWrap');
  var placeholder = document.getElementById('cameraPlaceholder');
  var canvas = document.getElementById('analysisCanvas');
  var curveCanvas = document.getElementById('curveCanvas');
  var deviceSelect = document.getElementById('deviceSelect');
  var btnStart = document.getElementById('btnStartCamera');
  var btnStop = document.getElementById('btnStopCamera');
  var btnRunTest = document.getElementById('btnRunTest');
  var diagnosticPanel = document.getElementById('diagnosticPanel');
  var sharpnessFill = document.getElementById('sharpnessFill');
  var sharpnessLabel = document.getElementById('sharpnessLabel');
  var statVerdict = document.getElementById('statVerdict');
  var statRecoveryTime = document.getElementById('statRecoveryTime');
  var statFocusMode = document.getElementById('statFocusMode');
  var statRecoveryPct = document.getElementById('statRecoveryPct');
  var statReference = document.getElementById('statReference');
  var statSettleLine = document.getElementById('statSettleLine');
  var statSettled = document.getElementById('statSettled');
  var statFrames = document.getElementById('statFrames');
  var statFps = document.getElementById('statFps');
  var statFrameTime = document.getElementById('statFrameTime');
  var statWebcam = document.getElementById('statWebcam');
  var statDistance = document.getElementById('statDistance');
  var distanceInput = document.getElementById('afDistance');
  var settleInput = document.getElementById('afSettle');

  var currentStream = null;
  var starting = false;
  var liveTimer = null;
  var testing = false;
  var testHandle = null;
  var reportedFps = 0;

  function escapeHtml(s) {
    var d = document.createElement('div');
    d.textContent = String(s);
    return d.innerHTML;
  }

  function setDiagnostic(items) {
    diagnosticPanel.innerHTML = items.map(function (it) {
      var sevClass = it.sev ? ' sev-' + it.sev : '';
      return '<div class="diagnostic-item' + sevClass + '"><span class="diag-icon" aria-hidden="true">' +
        '<svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/></svg>' +
        '</span><span>' + it.html + '</span></div>';
    }).join('');
  }

  // Same variance-of-Laplacian sharpness scorer as
  // webcam-sharpness-focus-test.json -- reused rather than reimplemented,
  // per this tool's own spec note, including the same tuned /70 scaling
  // divisor confirmed against real hardware on that tool.
  function measureVariance() {
    if (!currentStream || !video.videoWidth) return null;
    var w = video.videoWidth, h = video.videoHeight;
    var scale = Math.min(1, 140 / Math.max(w, h));
    var sw = Math.max(8, Math.round(w * scale));
    var sh = Math.max(8, Math.round(h * scale));
    canvas.width = sw;
    canvas.height = sh;
    var ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0, sw, sh);

    var data;
    try {
      data = ctx.getImageData(0, 0, sw, sh).data;
    } catch (e) {
      return null;
    }

    var gray = new Float32Array(sw * sh);
    for (var i = 0, p = 0; i < data.length; i += 4, p++) {
      gray[p] = data[i] * 0.299 + data[i + 1] * 0.587 + data[i + 2] * 0.114;
    }

    var lapSum = 0, lapSumSq = 0, count = 0;
    for (var y = 1; y < sh - 1; y++) {
      for (var x = 1; x < sw - 1; x++) {
        var idx = y * sw + x;
        var lap = 4 * gray[idx] - gray[idx - 1] - gray[idx + 1] - gray[idx - sw] - gray[idx + sw];
        lapSum += lap;
        lapSumSq += lap * lap;
        count++;
      }
    }
    if (!count) return null;
    var mean = lapSum / count;
    var variance = (lapSumSq / count) - (mean * mean);
    return Math.max(0, variance);
  }

  function updateLiveMeter() {
    var variance = measureVariance();
    if (variance === null) return null;
    var score = Math.max(0, Math.min(100, Math.round(variance / 70)));
    sharpnessFill.style.width = score + '%';
    sharpnessLabel.textContent = variance.toFixed(1);
    return variance;
  }

  function drawCurve(samples, settleLine, reference) {
    var w = curveCanvas.clientWidth || 300;
    var h = curveCanvas.clientHeight || 90;
    curveCanvas.width = w;
    curveCanvas.height = h;
    var ctx = curveCanvas.getContext('2d');
    ctx.clearRect(0, 0, w, h);
    if (samples.length < 2) return;
    var maxV = Math.max.apply(null, samples.concat([reference || 0])) * 1.1 || 1;
    var yOf = function (v) { return h - (v / maxV) * (h - 4) - 2; };
    if (settleLine) {
      ctx.strokeStyle = 'rgba(52,211,153,.9)';
      ctx.setLineDash([5, 4]);
      ctx.beginPath();
      ctx.moveTo(0, yOf(settleLine));
      ctx.lineTo(w, yOf(settleLine));
      ctx.stroke();
      ctx.setLineDash([]);
    }
    ctx.strokeStyle = '#7c5cff';
    ctx.lineWidth = 2;
    ctx.beginPath();
    samples.forEach(function (s, i) {
      var x = (i / (samples.length - 1)) * w;
      if (i === 0) ctx.moveTo(x, yOf(s)); else ctx.lineTo(x, yOf(s));
    });
    ctx.stroke();
  }

  // Guided near-far test. Phase 1 (3 s): sit still; the median sharpness
  // score becomes the reference and the settle line is the chosen share of
  // it (90% by default). Phase 2 (up to 10 s): raise a card close to the
  // lens. Frames are counted from the first frame below the settle line
  // until the score is back above it and stays there for 0.7 s; lock time =
  // frames / fps, recovery = settled score / reference. One sample per
  // camera frame via requestVideoFrameCallback where supported (timer-
  // driven otherwise, with frames derived from elapsed time x frame rate).
  var REF_MS = 3000, MOVE_MAX_MS = 10000, HOLD_MS = 700;

  function scheduleSample(fn) {
    if (video.requestVideoFrameCallback) {
      testHandle = { rvfc: true, id: video.requestVideoFrameCallback(function () { fn(performance.now()); }) };
    } else {
      testHandle = { rvfc: false, id: setTimeout(function () { fn(performance.now()); }, 33) };
    }
  }

  function cancelSample() {
    if (!testHandle) return;
    if (testHandle.rvfc) { if (video.cancelVideoFrameCallback) video.cancelVideoFrameCallback(testHandle.id); }
    else clearTimeout(testHandle.id);
    testHandle = null;
  }

  function runGuidedTest() {
    if (!currentStream || testing) return;
    testing = true;
    btnRunTest.disabled = true;
    var pct = parseFloat(settleInput.value);
    if (!(pct > 0 && pct <= 100)) pct = 90;
    var run = { pct: pct, start: performance.now(), phase: 'reference', refScores: [], samples: [], times: [], dropIdx: null, pending: null, settleIdx: null, crossings: 0 };
    statVerdict.textContent = 'Testing…';
    setDiagnostic([{ sev: '', html: '<strong>Step 1 of 2:</strong> sit still in your normal position for three seconds while the reference score is recorded.' }]);

    function step(t) {
      testHandle = null;
      if (!testing || !currentStream) return;
      var v = updateLiveMeter();
      if (v !== null) {
        if (run.phase === 'reference') {
          run.refScores.push(v);
          if (t - run.start >= REF_MS) {
            var sorted = run.refScores.slice().sort(function (a, b) { return a - b; });
            run.reference = sorted[Math.floor(sorted.length / 2)] || 0;
            run.settleLine = run.reference * run.pct / 100;
            run.phase = 'move';
            run.moveStart = t;
            statReference.textContent = run.reference.toFixed(1);
            statSettleLine.textContent = run.settleLine.toFixed(1) + ' (' + run.pct + '%)';
            setDiagnostic([{ sev: 'warn', html: '<strong>Step 2 of 2: raise the printed page to ' + escapeHtml(distanceInput.value || '22') + ' cm from the lens now</strong> and hold it steady in the centre until the test finishes.' }]);
          }
        } else {
          run.samples.push(v);
          run.times.push(t);
          var i = run.samples.length - 1;
          var above = v >= run.settleLine;
          if (run.dropIdx === null) {
            if (!above) run.dropIdx = i;
          } else if (above) {
            if (run.pending === null) run.pending = i;
            if (t - run.times[run.pending] >= HOLD_MS) { run.settleIdx = run.pending; finish(run); return; }
          } else if (run.pending !== null) {
            run.crossings++; // touched the line then fell back: hunting
            run.pending = null;
          }
          if (i % 3 === 0) drawCurve(run.samples, run.settleLine, run.reference);
          if (t - run.moveStart >= MOVE_MAX_MS) { finish(run); return; }
        }
      }
      scheduleSample(step);
    }
    scheduleSample(step);
  }

  function finish(run) {
    testing = false;
    cancelSample();
    btnRunTest.disabled = !currentStream;
    drawCurve(run.samples, run.settleLine, run.reference);
    var moveSecs = run.times.length > 1 ? (run.times[run.times.length - 1] - run.times[0]) / 1000 : 0;
    var fps = video.requestVideoFrameCallback && moveSecs > 0.5 ? (run.samples.length - 1) / moveSecs : (reportedFps || 30);
    statFps.textContent = fps.toFixed(1) + ' fps';
    statFrameTime.textContent = (1000 / fps).toFixed(1) + ' ms';
    var dist = parseFloat(distanceInput.value);
    statDistance.textContent = !(dist > 0) ? '—' : dist < 50
      ? dist + ' cm is closer than the roughly 50 cm a fixed-focus webcam is set for, so only a camera with real autofocus can sharpen it.'
      : dist + ' cm is inside the range a fixed-focus webcam already covers, so this result does not prove the camera can refocus.';

    if (run.dropIdx === null) {
      statRecoveryTime.textContent = '—';
      statFrames.textContent = '—';
      statSettled.textContent = '—';
      statRecoveryPct.textContent = '—';
      statVerdict.textContent = 'No blur detected — the score never fell below the settle line. Hold the page closer and fill the centre with it, then try again.';
      setDiagnostic([{ sev: 'warn', html: 'Nothing to time: the score never dropped below the settle line.' }]);
      return;
    }
    if (run.settleIdx !== null) {
      var frames = video.requestVideoFrameCallback ? run.settleIdx - run.dropIdx : Math.round((run.times[run.settleIdx] - run.times[run.dropIdx]) / 1000 * fps);
      var lock = frames / fps;
      var settled = 0, n = 0;
      for (var k = run.settleIdx; k < run.samples.length; k++) { settled += run.samples[k]; n++; }
      settled /= n;
      statFrames.textContent = String(frames);
      statSettled.textContent = settled.toFixed(1);
      statRecoveryPct.textContent = (settled / run.reference * 100).toFixed(1) + '%';
      statRecoveryTime.textContent = lock.toFixed(2) + ' s';
      statVerdict.textContent = (lock <= 1 ? 'Fast lock: fine for moving objects in and out of frame.'
        : lock <= 2 ? 'Usable: hold each object still for a two-second beat before talking about it.'
        : 'Slow: add light in front of you or move the object farther away, then retest.') +
        (run.crossings ? ' The score overshot the settle line ' + run.crossings + '× before settling (focus hunting).' : '');
      setDiagnostic([{ sev: 'ok', html: '<strong>Autofocus locked in ' + lock.toFixed(2) + ' s</strong> (' + frames + ' frames at ' + fps.toFixed(1) + ' fps).' }]);
    } else {
      var best = Math.max.apply(null, run.samples.slice(run.dropIdx));
      statFrames.textContent = 'Never';
      statSettled.textContent = best.toFixed(1) + ' (best)';
      statRecoveryPct.textContent = (best / run.reference * 100).toFixed(1) + '%';
      statRecoveryTime.textContent = 'Did not settle';
      statVerdict.textContent = 'Never reached the settle line: the subject is inside the near limit, the camera has fixed focus, or the room is too dark. Move it farther away or add light and retest.';
      setDiagnostic([{ sev: 'warn', html: '<strong>Focus did not lock</strong> within 10 seconds of the blur.' }]);
    }
  }

  // Same stopStream()/describeError()/populateDeviceSelect() pattern as
  // webcam-test-online's own script (see this project's CLAUDE.md -- every
  // camera tool copies this teardown block rather than importing a shared file).
  function stopStream() {
    if (liveTimer) { clearInterval(liveTimer); liveTimer = null; }
    testing = false;
    cancelSample();
    if (currentStream) {
      currentStream.getTracks().forEach(function (t) { t.stop(); });
      currentStream = null;
    }
    video.srcObject = null;
    previewWrap.classList.remove('is-active');
    placeholder.style.display = 'flex';
    btnStop.disabled = true;
    btnRunTest.disabled = true;
    sharpnessFill.style.width = '0%';
    sharpnessLabel.textContent = '—';
  }

  function describeError(err) {
    switch (err && err.name) {
      case 'NotAllowedError':
      case 'PermissionDeniedError':
        return { sev: 'error', html: '<strong>Camera access was blocked.</strong> Allow access from your browser’s address-bar icon or site settings, then try again.' };
      case 'NotFoundError':
      case 'DevicesNotFoundError':
        return { sev: 'error', html: '<strong>No camera was detected.</strong> Connect a webcam and reload this page.' };
      case 'NotReadableError':
      case 'TrackStartError':
        return { sev: 'error', html: '<strong>Your camera is already in use</strong> by another app or browser tab.' };
      case 'OverconstrainedError':
        return { sev: 'error', html: '<strong>This camera doesn’t support the requested settings.</strong> Try another camera from the list.' };
      case 'SecurityError':
        return { sev: 'error', html: '<strong>Camera access requires HTTPS.</strong>' };
      default:
        return { sev: 'error', html: '<strong>Something went wrong starting the camera.</strong> ' + escapeHtml((err && err.message) || 'Unknown error') + '.' };
    }
  }

  function populateDeviceSelect(devices, currentDeviceId) {
    var cams = devices.filter(function (d) { return d.kind === 'videoinput'; });
    deviceSelect.innerHTML = '';
    cams.forEach(function (d, i) {
      var opt = document.createElement('option');
      opt.value = d.deviceId;
      opt.textContent = d.label || ('Camera ' + (i + 1));
      if (d.deviceId === currentDeviceId) opt.selected = true;
      deviceSelect.appendChild(opt);
    });
    deviceSelect.disabled = cams.length === 0;
  }

  function startStream(deviceId) {
    if (starting) return;
    starting = true;
    stopStream();
    setDiagnostic([{ sev: '', html: 'Requesting camera access…' }]);
    btnStart.disabled = true;

    navigator.mediaDevices.getUserMedia({ video: deviceId ? { deviceId: { exact: deviceId } } : true, audio: false })
      .then(function (stream) {
        currentStream = stream;
        video.srcObject = stream;
        placeholder.style.display = 'none';
        previewWrap.classList.add('is-active');
        return video.play().catch(function () {}).then(function () { return stream; });
      })
      .then(function (stream) {
        var track = stream.getVideoTracks()[0];
        var settings = track.getSettings ? track.getSettings() : {};
        var caps = track.getCapabilities ? (function () { try { return track.getCapabilities(); } catch (e) { return null; } })() : null;
        btnStop.disabled = false;
        btnRunTest.disabled = false;
        statFocusMode.textContent = (caps && caps.focusMode && caps.focusMode.length) ? caps.focusMode.join(', ') : 'Not reported';
        statWebcam.textContent = track.label || 'Not selected';
        reportedFps = settings.frameRate || 0;
        setDiagnostic([{ sev: 'ok', html: '<strong>Camera is live.</strong> Point at something detailed, then click Run Guided Focus Test.' }]);
        liveTimer = setInterval(updateLiveMeter, 250);
        return navigator.mediaDevices.enumerateDevices().then(function (devices) {
          populateDeviceSelect(devices, settings.deviceId);
        });
      })
      .catch(function (err) { setDiagnostic([describeError(err)]); stopStream(); })
      .finally(function () { starting = false; btnStart.disabled = false; });
  }

  btnStart.addEventListener('click', function () { startStream(deviceSelect.value); });
  btnStop.addEventListener('click', function () {
    stopStream();
    setDiagnostic([{ sev: '', html: 'Camera stopped.' }]);
  });
  deviceSelect.addEventListener('change', function () { if (currentStream) startStream(deviceSelect.value); });
  btnRunTest.addEventListener('click', runGuidedTest);

  window.addEventListener('pagehide', stopStream);
  document.addEventListener('visibilitychange', function () {
    if (document.visibilityState === 'hidden') stopStream();
  });

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setDiagnostic([{ sev: 'error', html: '<strong>Your browser doesn’t support camera access.</strong>' }]);
    btnStart.disabled = true;
  }
})();
